<div class="card"><h2>Failed Uploads</h2><table><tr><th>Title</th><th>Channel</th><th>Retries</th><th>Error</th><th></th></tr><?php foreach(array_filter($videos,fn($v)=>$v['status']==='Failed') as $v):?><tr><td><?=e($v['title'])?></td><td><?=e($v['channel_name'])?></td><td><?=e((string)$v['retry_count'])?></td><td class="error-text"><?=e($v['last_error'])?></td><td><form method="post"><input type="hidden" name="_csrf" value="<?=e($security->csrf())?>"><input type="hidden" name="action" value="retry"><input type="hidden" name="id" value="<?=$v['id']?>"><button class="btn primary">Retry</button></form></td></tr><?php endforeach;?></table></div>
